<?php
namespace App\Core\Connectors\Drivers;
use App\Core\Agents\Contracts\RiskLevel;use App\Core\Connectors\DTO\{ConnectorAction,ConnectorResult};use App\Core\Security\OutboundEndpointPolicy;use App\Models\ConnectorConnection;
final class AutomationWebhookConnector extends AbstractConnector {public function id():string{return 'automation_webhook';}public function label():string{return 'n8n / Zapier / Make / Webhook';}public function actions():array{return [new ConnectorAction('send','Send a signed JSON event to an automation webhook.',RiskLevel::ExternalWrite,['type'=>'object','properties'=>['event'=>['type'=>'string'],'payload'=>['type'=>'object']],'required'=>['event','payload']],['webhook.send'])];}public function configurationSchema():array{return ['credentials'=>['signing_secret'=>['type'=>'password','required'=>false]],'fields'=>['url'=>['type'=>'url','required'=>true],'provider'=>['type'=>'select','options'=>['custom','n8n','zapier','make']]]];}public function test(ConnectorConnection $c):bool{try{app(OutboundEndpointPolicy::class)->assertAllowed((string)(($c->configuration??[])['url']??''));return true;}catch(\Throwable){return false;}}public function execute(ConnectorConnection $c,string $action,array $a):ConnectorResult{$this->action($action);$url=(string)(($c->configuration??[])['url']??'');app(OutboundEndpointPolicy::class)->assertAllowed($url);$body=['event'=>(string)$a['event'],'payload'=>$a['payload'],'sent_at'=>now()->toIso8601String()];$secret=$c->credential('signing_secret');$headers=['X-Enverif-Event'=>(string)$a['event']];if($secret)$headers['X-Enverif-Signature']='sha256='.hash_hmac('sha256',json_encode($body,JSON_UNESCAPED_SLASHES),$secret);return ConnectorResult::success($this->client($headers)->post($url,$body)->throw()->json());}}
